'use strict';

const fs = require('node:fs');
const realLockfile = require(process.env.PI_AGENT_REAL_PROPER_LOCKFILE);

let integrationLockPath;
let compromiseTriggered = false;

function record(event, detail = {}) {
  fs.appendFileSync(
    process.env.PI_AGENT_LOCK_RACE_LOG,
    `${JSON.stringify({ event, ...detail })}\n`,
  );
}

async function lock(targetPath, options = {}) {
  const integration = Boolean(options.lockfilePath);
  const delegatedOptions = { ...options };
  if (integration) {
    integrationLockPath = options.lockfilePath;
    delegatedOptions.stale = 2000;
    delegatedOptions.update = 1000;
    delegatedOptions.onCompromised = (error) => {
      record('integration-compromised', { code: error.code });
      options.onCompromised(error);
    };
  } else {
    record('settings-attempt');
  }

  let release;
  try {
    release = await realLockfile.lock(targetPath, delegatedOptions);
  } catch (error) {
    if (!integration && error.code === 'ELOCKED') {
      record('settings-contended');
      if (!compromiseTriggered) {
        compromiseTriggered = true;
        fs.rmdirSync(integrationLockPath);
        record('integration-lock-removed');
      }
    }
    throw error;
  }

  record(integration ? 'integration-acquired' : 'settings-acquired');
  return async () => {
    record(integration ? 'integration-release' : 'settings-release');
    return release();
  };
}

module.exports = { lock };
